  "about_items": [
    {
      "n": "#272·19",
      "text": "This is a milky white silk slip dress with a deep V-neckline and delicate spaghetti straps, featuring subtle sparkles that catch the light without being overpowering. Its fluid, A-line silhouette drapes elegantly over your hips and thighs, reaching just above your ankles to create a sophisticated and effortless look."
    },
    {
      "n": "#452·16",
      "text": "This is a luxurious multi-strand pearl necklace featuring five distinct tiers of lustrous white pearls, all gathered at the top with a contrasting black satin bow that adds a modern, chic element to this classic piece."
    },
    {
      "n": "#344·39",
      "text": "This is a sophisticated beige leather tote bag featuring clean lines and structured panels, accented by a sleek silver-toned clasp closure on the front flap and comfortable top handles that are perfect for carrying your daily essentials."
    },
    {
      "n": "#409·06",
      "text": "These are soft beige suede boots featuring a plush, slip-on design that fits snugly around your calf, opening at the toe to create a stylish peep-toe silhouette that adds an air of relaxed elegance to your polished office look."
    },
    {
      "n": "#442·39",
      "text": "This is a refined ginger leather belt featuring smooth stitching and a sturdy silver-toned rectangular buckle that provides a crisp contrast against the softer textures of your outfit while defining your silhouette with a clean, professional edge."
    }
  ]
}
